// Gom thông tin lỗi từ Error Trigger
const e = $input.first().json;
const exec = e.execution || {};
const trig = e.trigger || {};
const err = exec.error || trig.error || {};
return [{ json: {
  workflow_name: (e.workflow && e.workflow.name) || 'Không rõ',
  workflow_id: (e.workflow && e.workflow.id) || null,
  node_name: exec.lastNodeExecuted || (err.node && err.node.name) || null,
  execution_id: exec.id != null ? String(exec.id) : null,
  execution_url: exec.url || null,
  error_message: String(err.message || 'Lỗi không rõ').slice(0, 2000),
  details: {
    mode: exec.mode || trig.mode || null,
    description: err.description || null,
    stack: String(err.stack || '').split('\n').slice(0, 6).join('\n'),
    execution_url: exec.url || null,
  },
} }];

