const info = $('Gom thông tin lỗi').first().json;
const jobId = $input.first().json.id;
const lines = [
  `[n8n] Lỗi ở workflow "${info.workflow_name}"` + (info.node_name ? `, node "${info.node_name}"` : ''),
  info.error_message,
  `failed_jobs #${jobId}` + (info.execution_id ? ` · execution ${info.execution_id}` : ''),
];
if (info.execution_url) lines.push(info.execution_url);
return [{ json: { text: lines.join('\n'), failed_job_id: jobId } }];
